      13'd8189: T = 16'd16388;
      13'd8190: T = 16'd16387;
      13'd8191: T = 16'd16385;
      default: T = 16'd0;
    endcase
  end

  // output: round shift by q + g (y = ((({Y,0} >> s) + 1) >> 1)), 0 on underflow
  wire [16:0] o_yx = {T, 1'b0};
  reg  [13:0] o_t;
  always @(*) begin
    case (q)
      5'd0: o_t = o_yx[16:3];
      5'd1: o_t = {1'd0, o_yx[16:4]};
      5'd2: o_t = {2'd0, o_yx[16:5]};
      5'd3: o_t = {3'd0, o_yx[16:6]};
      5'd4: o_t = {4'd0, o_yx[16:7]};
      5'd5: o_t = {5'd0, o_yx[16:8]};
      5'd6: o_t = {6'd0, o_yx[16:9]};
      5'd7: o_t = {7'd0, o_yx[16:10]};
      5'd8: o_t = {8'd0, o_yx[16:11]};
      5'd9: o_t = {9'd0, o_yx[16:12]};
      5'd10: o_t = {10'd0, o_yx[16:13]};
      5'd11: o_t = {11'd0, o_yx[16:14]};
      5'd12: o_t = {12'd0, o_yx[16:15]};
      5'd13: o_t = {13'd0, o_yx[16:16]};
      default: o_t = 14'd0;
    endcase
  end
  wire [14:0] o_tp1 = {1'b0, o_t} + 15'd1;
  wire [13:0] o_yr  = o_tp1[14:1];
  wire [12:0] y_c = under ? 13'd0 : o_yr[12:0];

  // output register (loaded when a result is valid, held otherwise)
  always @(posedge clk) begin
    if (v_r) y <= y_c;
  end
endmodule
